<template><section class="module-view browser-chrome">
  <div class="browser-navigation"><nav class="browser-tabs" aria-label="Differential expression views"><button v-for="item in ['Volcano','Heatmap','Gene table','Source']" :key="item" :aria-pressed="view===item" @click="view=item;loadHeatmap()">{{item}}</button></nav></div>
  <div class="browser-filters">
    <label class="browser-select">Dataset <select v-model="selected" @change="load" :title="data ? data.dataset+' · '+data.label : ''"><option v-for="(item,i) in catalogue" :key="item.asset" :value="i">{{item.dataset.split('_').pop()}} · {{item.label}}</option></select></label>
    <details v-if="view==='Volcano'"><summary>Highlight and thresholds</summary><div class="filter-detail"><label class="browser-input"><span>|log₂ FC|</span><input aria-label="Absolute log2 fold-change" type="number" v-model.number="fold" min="0" step="0.1"/></label><label class="browser-input"><span>Adjusted P</span><input aria-label="Adjusted P threshold" type="number" v-model.number="pvalue" min="0.000000000001" max="1" step="0.01"/></label><label class="browser-input"><span>Gene</span><input aria-label="Highlight gene" v-model="gene" maxlength="80"/></label></div></details>
    <template v-if="view==='Gene table'"><label class="browser-input"><span>Find gene</span><input v-model="search"/></label><label class="browser-select">Sort <select v-model="sort"><option value="p">Adjusted P</option><option value="fold">Absolute fold change</option><option value="gene">Gene</option></select></label></template>
  </div>
  <div class="module-stage" :class="{'is-plot':view==='Volcano'}">
    <p v-if="error" role="alert">{{error}} <button @click="load">Retry</button></p><p v-if="busy" role="status">Loading selected comparison…</p>
    <template v-if="data">
      <ScatterPlot v-if="view==='Volcano'" :rows="points" x-label="log₂ fold change" y-label="−log₁₀ adjusted P" title="Differential-expression" :fullscreen="fullscreen" @fullscreen="toggleFullscreen"/>
      <div v-if="view==='Heatmap'" class="heatmap-view"><p v-if="heatError" role="alert">{{heatError}} <button @click="loadHeatmap(true)">Retry heatmap</button></p><p v-else-if="!heat" role="status">Loading source-selected genes…</p><template v-else><div class="heatmap-scroll" ref="heatmap"><table class="heatmap" :style="{minWidth:(100+heatLabels.length*18)+'px'}"><tbody><tr v-for="row in heat" :key="row.gene"><th scope="row">{{row.gene}}</th><td v-for="(value,i) in row.expression" :key="i" :style="{background:heatColor(value)}" :title="heatInfo?`${row.gene}, ${heatLabels[i]}: ${value}`:undefined"/></tr></tbody><tfoot><tr><th scope="row">Source samples</th><th v-for="(label,i) in heatLabels" :key="i" scope="col"><span>{{label}}</span></th></tr></tfoot></table></div><BrowserToolbar :actions="['fullscreen','info','download']" :fullscreen="fullscreen" :can-zoom-in="heatZoom<4" :can-zoom-out="heatZoom>1" @fullscreen="toggleFullscreen" @zoomIn="heatZoom=Math.min(4,heatZoom*1.25)" @zoomOut="heatZoom=Math.max(1,heatZoom/1.25)" :zoom-percent="Math.round(heatZoom*100)" :info-enabled="heatInfo" @info="heatInfo=!heatInfo" @reset="heatZoom=1;heatInfo=true" @fit="heatZoom=1" @download="downloadHeatmap"/></template></div>
      <div v-if="view==='Gene table'"><p v-if="!tableRows.length" role="status">No genes match this filter in the selected comparison. <button @click="search=''">Clear filter</button></p><table><thead><tr><th>Gene</th><th>log₂ fold change</th><th>−log₁₀ adjusted P</th></tr></thead><tbody><tr v-for="row in tableRows.slice(page*50,(page+1)*50)" :key="row[0]"><td><button @click="gene=row[0];view='Volcano'">{{row[0]}}</button></td><td>{{row[1]??'Not reported'}}</td><td>{{row[2]??'Not reported'}}</td></tr></tbody></table><div class="table-actions"><button :disabled="page===0" @click="page--">Previous</button><span>{{page+1}} / {{Math.max(1,Math.ceil(tableRows.length/50))}}</span><button :disabled="(page+1)*50>=tableRows.length" @click="page++">Next</button><button @click="download">Download comparison</button></div></div>
      <div v-if="view==='Source'" class="source-panel"><h2>Source &amp; methods</h2><p>The complete source comparison is retained. Dataset and comparison columns are stored once; numeric values are not rounded. Non-numeric source statistics remain missing. The heatmap is retrieved only when its tab is opened.</p><p>{{data.dataset}} · {{data.label}}</p><p>Source SHA-256: {{data.source.sha256}}</p><div class="table-actions"><button @click="download">Download comparison</button><a :href="data.source.url" target="_blank" rel="noopener">Original source table ↗</a></div></div>
    </template>
    <BrowserToolbar v-if="['Gene table','Source'].includes(view)" navigation-only :fullscreen="fullscreen" @fullscreen="toggleFullscreen"/>
  </div>
  <footer class="browser-footer"><span v-if="data">{{data.dataset.split('_').pop()}} · {{data.label}} · {{data.rows.length.toLocaleString()}} genes</span><span v-else>PanKbase pseudobulk RNA · v3.3</span><p class="description" v-if="view==='Volcano'">Red/blue: positive/negative fold change passing both thresholds. Orange: selected gene. Cohort comparison, not a temporal trajectory.</p><div v-if="view==='Heatmap' && heat" class="heatmap-key"><span>{{heat.length}} genes × {{heatLabels.length}} samples</span><span>Per-gene z score</span><span>−3</span><i class="heatmap-gradient" aria-hidden="true"/><span>+3</span><span><i class="missing-swatch"/> Missing</span></div><p class="description" v-if="view==='Heatmap'">Source-selected genes · Z-normalized expression · Sample IDs on x axis, original source order. Blue/white/red: −3/0/+3. Per-gene z scores are not absolute expression.</p></footer>
</section></template>
<script>
import { interpolateRdBu } from 'd3';
import { localJson, downloadText } from './assets.mjs';
import { assetUrl } from './source.mjs';
import { readBioIndex } from './data.mjs';
import ScatterPlot from './ScatterPlot.vue';
import BrowserToolbar from './BrowserToolbar.vue';
import browserControls from './browserControls.mjs';
import { validateHeatmapLabels } from './heatmapLabels.mjs';
import { downloadHeatmapSvg } from './plotExport.mjs';
export default { components:{ScatterPlot,BrowserToolbar},mixins:[browserControls],props:['context'],data:()=>({catalogue:[],selected:0,data:null,busy:false,error:'',gene:'',view:'Volcano',heatZoom:1,heatInfo:true,fold:1.5,pvalue:0.05,search:'',sort:'p',page:0,heat:null,heatLabels:[],heatError:'',heatPending:false,serial:0}),
  computed:{points(){return this.data.rows.map(([name,x,y])=>({x,y,label:name,highlight:name===this.gene,color:name===this.gene?'#f59e0b':Math.abs(x)>this.fold&&y>-Math.log10(this.pvalue)?x>0?'#bf2c23':'#2f67b1':'#94a3b8'}));},tableRows(){const rows=this.data.rows.filter(r=>r[0].toLowerCase().includes(this.search.toLowerCase()));return rows.sort((a,b)=>this.sort==='gene'?a[0].localeCompare(b[0]):this.sort==='fold'?Math.abs(b[1]??0)-Math.abs(a[1]??0):(b[2]??-Infinity)-(a[2]??-Infinity));}},
  watch:{search(){this.page=0;},sort(){this.page=0;}},
  async mounted(){this.gene=this.context.geneSymbol||'';await this.load();},
  methods:{downloadHeatmap(){downloadHeatmapSvg(this.heat,this.heatColor,'DE-heatmap.svg',this.heatLabels);},async load(){const token=++this.serial;this.error='';this.busy=true;this.data=null;this.heat=null;this.heatLabels=[];this.heatPending=false;this.heatError='';this.page=0;try{if(!this.catalogue.length){this.catalogue=(await localJson('data/manifest.json')).de;const exact=this.catalogue.findIndex(x=>x.dataset===this.context.datasetId);const related=this.catalogue.findIndex(x=>x.dataset.split('_').pop().toLowerCase()===(this.context.cellType||'').replaceAll(' ','').toLowerCase());this.selected=exact>=0?exact:related>=0?related:0;}const data=await localJson('data/'+this.catalogue[this.selected].asset);if(token===this.serial){this.data=data;this.loadHeatmap();}}catch(e){if(token===this.serial)this.error=e.message;}finally{if(token===this.serial)this.busy=false;}},async loadHeatmap(retry=false){if(!this.data||this.view!=='Heatmap'||this.heat||this.heatPending)return;const token=this.serial;this.heatPending=true;this.heatError='';try{const [response,metadata]=await Promise.all([readBioIndex(assetUrl('supplement/heatmaps/'+this.data.dataset+'.json')),readBioIndex(assetUrl('supplement/heatmaps/'+this.data.dataset+'.samples.json'))]);if(token!==this.serial)return;if(!Array.isArray(response.data)||!response.data.every(r=>r.dataset===this.data.dataset&&r.comparison===this.data.label&&Array.isArray(r.expression)))throw new Error('Heatmap context does not match the selected comparison.');this.heatLabels=validateHeatmapLabels(metadata,response.data,this.data.dataset);if(token===this.serial)this.heat=response.data;}catch(e){if(token===this.serial)this.heatError=e.message;}finally{if(token===this.serial)this.heatPending=false;}},heatColor(value){return Number.isFinite(value)?interpolateRdBu(0.5-Math.max(-3,Math.min(3,value))/6):'#e2e8f0';},download(){downloadText(['dataset\tcomparison\tgene\tlogFoldChange\t-log10P',...this.data.rows.map(r=>[this.data.dataset,this.data.label,...r.map(v=>v??'NA')].join('\t'))].join('\n'),this.data.dataset+'-'+this.data.comparison+'.tsv');}},
};
</script>
